    from collections import defaultdict
    adj = defaultdict(set)
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    best = float('inf')
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        for u in queue:
            for w in adj[u]:
                if w not in dist:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    queue.append(w)
